-- Binder: BCD dupe tracker — schema + master collection data
-- Run this ONCE in Supabase SQL Editor.


create table if not exists accounts (
  id uuid primary key default gen_random_uuid(),
  user_id uuid not null references auth.users(id) on delete cascade,
  name text not null,
  is_main boolean not null default false,
  created_at timestamptz not null default now()
);
alter table accounts enable row level security;
create policy "accounts select own" on accounts for select using (auth.uid() = user_id);
create policy "accounts insert own" on accounts for insert with check (auth.uid() = user_id);
create policy "accounts update own" on accounts for update using (auth.uid() = user_id);
create policy "accounts delete own" on accounts for delete using (auth.uid() = user_id);

create table if not exists collections (
  id uuid primary key default gen_random_uuid(),
  name text not null,
  category text not null check (category in ('group','solo')),
  type text not null check (type in ('regular','am'))
);
alter table collections enable row level security;
create policy "collections read all" on collections for select using (auth.role() = 'authenticated');

create table if not exists card_slots (
  id uuid primary key default gen_random_uuid(),
  collection_id uuid not null references collections(id) on delete cascade,
  label text not null,
  slot_order int not null default 0
);
alter table card_slots enable row level security;
create policy "card_slots read all" on card_slots for select using (auth.role() = 'authenticated');

create table if not exists card_ownership (
  id uuid primary key default gen_random_uuid(),
  account_id uuid not null references accounts(id) on delete cascade,
  card_slot_id uuid not null references card_slots(id) on delete cascade,
  quantity int not null default 0,
  unique(account_id, card_slot_id)
);
alter table card_ownership enable row level security;
create policy "ownership select own" on card_ownership for select
  using (exists (select 1 from accounts a where a.id = card_ownership.account_id and a.user_id = auth.uid()));
create policy "ownership insert own" on card_ownership for insert
  with check (exists (select 1 from accounts a where a.id = card_ownership.account_id and a.user_id = auth.uid()));
create policy "ownership update own" on card_ownership for update
  using (exists (select 1 from accounts a where a.id = card_ownership.account_id and a.user_id = auth.uid()));
create policy "ownership delete own" on card_ownership for delete
  using (exists (select 1 from accounts a where a.id = card_ownership.account_id and a.user_id = auth.uid()));

